cd /tmp/vally-eval-trial-mQDG1F && T=.copilot-tracking/skraft-plans/pricing && mkdir -p $T/features $T/details/2026-10-07 $T/evidence/2026-10-07/discount tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $T/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier discount at checkout
  A returning customer's loyalty tier is reflected in the checkout total.

  # SETTLED: AC-1..AC-3 (explicit values in ac.md).
  # NOT SETTLED: AC-4 (see @needs-clarification) and the Platinum tier (no value exists).

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  # UNSETTLED: AC-4's title says the reduction rounds "in the customer's favour",
  # but its value (7 cents charged on a 7 cent subtotal, i.e. no reduction) favours the
  # business; a customer-favourable rounding would charge 6 cents. Value kept verbatim from
  # ac.md; escalated to DISCUSS. Do not implement or test until resolved.
  @edge-case @needs-clarification
  Scenario: Bronze customer with a tiny basket is charged a whole-cent amount
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents

  # NOT DECIDED: Platinum tier. The business has agreed no reduction, so no scenario exists.
  # Deliberately absent: do not invent a value.
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Bronze_customer_is_charged_the_Bronze_price()
    {
        var useCase = new CalculateLoyaltyDiscount();

        var quote = useCase.Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
D=$T/evidence/2026-10-07/discount
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > $D/acceptance-red.stdout 2>&1; echo $? > $D/acceptance-red.exit; git rev-parse HEAD > $D/acceptance-red.rev; cat $D/acceptance-red.exit; grep -E "Assert|Expected|Actual|error|Failed" $D/acceptance-red.stdout | head

